def separate_paren_groups(paren_string: str) -> List[str]:
    paren_stack = []
    groups = []
    current_group = ""

    for char in paren_string:
        if char == " ":
            continue

        if char == "(":
            paren_stack.append(char)
            current_group += char
        elif char == ")":
            paren_stack.pop()
            current_group += char

            if not paren_stack:
                groups.append(current_group)
                current_group = ""

