def max_product(num_str: str, N: int, K: int) -> int:
    if K > N - 1 or K < 0:
        raise ValueError("Invalid input: K must be between 0 and N-1")

    from itertools import combinations

    # Generate all possible combinations of K multiplication signs
    product_combinations = combinations(range(N), K)

    # Initialize the maximum product to a very small number
    max_product = float('-inf')

    # Calculate the product for each combination
    for combination in product_combinations:
        product = 1
        for i in range(N):
            if combination[i] == i:
                product *= int(num_str[i])
            else:
                product *= int('1' * (N - i - combination[i]))
        max_product = max(max_product, product)

    return int(max_product)
