    if check_digit == 'X':
        check_digit = chr(87)  # 'X' represented as 'x' in ASCII

    if isbn[-1] == check_digit:
        return "Right"
    else:
        correction_position = int(isbn[-1]) - int(check_digit)
        corrected_isbn = isbn[:-1] + chr(ord(isbn[-1]) - (2 * correction_position) % 10)
