def verify_isbn(isbn: str) -> str:
    def checksum(isbn: str) -> int:
        digits = [int(d) for d in isbn] + [10 if isbn[-1] == 'X' else int(isbn[-1])]
        return sum(d * (3 if i % 2 == 0 else 1) for i, d in enumerate(digits))

    corrected_isbn = isbn
    if checksum(isbn) != 10:
        # Calculate the correct checksum digit
        correct_checksum = 10 - checksum(isbn)
        # Replace the last digit with the correct checksum digit
        corrected_isbn = isbn[:-1] + chr(correct_checksum + ord('0'))

    return "Right" if checksum(corrected_isbn) == 10 else corrected_isbn
