def count_passing_ways(n: int, m: int) -> int:
    if m < n:
        return 0  # It's impossible to return a ball more times than there are students

    # Initialize DP table
    dp = [0] * (m + 1)
    dp[0] = 1  # Starting point

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            dp[i] = (dp[i] + dp[i - 1]) % 1000000007  # Kelly's urn theorem

