from typing import List

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    def format_coefficient(coef, degree):
        if coef == 0:
            return ""
        abs_coefficient = abs(coef)
        sign = "+" if coef > 0 else "-"
        if abs_coefficient == 1 and degree == 1:
            return sign + "x"
        if degree == 2:
            return sign + f"{abs_coefficient}x^2"
        return sign + f"{abs_coefficient}x^{degree}"

    if n < 0:
        raise ValueError("Number of coefficients must be non-negative.")
    if any(coeff < 0 for coeff in coeffs):
        raise ValueError("Coefficients must be non-negative.")

    polynomial = ""
    for degree in range(n, -1, -1):
        coeff = coeffs[degree]
        formatted_coeff = format_coefficient(coeff, degree)
        if formatted_coeff:
            polynomial += formatted_coeff

    return polynomial.lstrip("+")  # Remove leading '+'
