        dp[i][0] = 1  # There's one way to arrange 0 pots of any type

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            dp[i][j] = dp[i][j - 1]  # Default, no pots of current type
            if j - a[i - 1] >= 0:
                dp[i][j] = (dp[i][j] + dp[i - 1][j - a[i - 1]]) % mod

