def mod_inverse(a, b):
    if a <= 0 or b <= 0:
        raise ValueError("A and B must be positive integers.")
    if not (a % b == 0):
        return None

    x, y = 0, 1
    while b != 0:
        quotient = a // b
        x, y = y, (x - quotient * y)
        a, b = b, a - quotient * b

    return x % b
```

