def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    def is_possible(min_students):
        cnt = 0
        for i in range(min_students):
            if i < n // 2:
                if heights[i] > heights[i + 1]:
                    cnt += 1
            else:
                if heights[i] < heights[i - 1]:
                    cnt += 1
        return cnt == 0

    left, right = 1, n
    while left < right:
        mid = (left + right + 1) // 2
        if is_possible(mid):
            left = mid
        else:
            right = mid - 1

    return left
```

