def min_groups(w, n, prices):
    if n == 0 or w == 0:
        return 0

    total_price = sum(prices)
    if total_price > w:
        return -1

    dp = [0] * (w + 1)
    dp[0] = 1  # Base case: one group

    for price in prices:
        for j in range(w, price - 1, -1):
            dp[j] = max(dp[j], dp[j - price] + 1)

    return dp[w]
